head.script:
scwin.gBondYn = js_bond_yn;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.hideDebugCtrls();
        await scwin.readSchdl();

        // 채권팀일시 저장버튼 보이지않게 한다.
        if (scwin.gBondYn === 'Y') {
            btn_Save.hide();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26604.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_SDATE_onclick
 * @description img_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_WRTRPT_SUBMIT_SCHDL_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26604.img_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26604.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26604.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Comcompany_OnLoadCompleted
 * @description dts_Comcompany 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Comcompany_OnLoadCompleted = function(rowcount) {
    try {
        dts_Comcompany.setCellData(1, "FLAG", "Y");

        // 제출마감일이 과거일자면 저장 버튼이 보이지않게 한다.
        const gSUBMIT_SCHDL_DD = dts_Comcompany.getCellData(1, "WRTRPT_SUBMIT_SCHDL_DD");
        if (gSUBMIT_SCHDL_DD < $c.ut.cGetToday("yyyymmdd")) {
            btn_Save.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26604.dts_Comcompany_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save); ///('trs_Save.OnFail()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26604.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        const fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26604.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSchdl
 * @description read Schdl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSchdl = async function() {
    const parentWin = $c.frame.path("../");
    const paramObj = parentWin.gParamObj;
    if (paramObj === undefined) return;
    const vIBAS_YY = paramObj.param1;
    const vIBAS_ACNTCLS_MM = paramObj.param2;
    const vIGUBUN = paramObj.param3;
    url += "&BAS_YY=" + vIBAS_YY;
    url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
    url += "&GUBUN=" + vIGUBUN;
    url += "&SCREN_ID=" + 'ULDSTF26604.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // alert('[url]'+url);
    const sbmOptions = {
        id : "sbm_dts_Comcompany",
        action : "/SubmitStatus.do",
        ref : "",
        target : "dts_Comcompany=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (confirm("수정하시겠습니까?")) {
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/SubmitStatus.do",
            ref : "dts_Comcompany",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else {
        return false;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    txb_WRTRPT_KIND_CD.hide();
};
